  {
    "id": "9e33d4d759ec4d769faeb5bd4cdb5dc9",
    "cell_type": "code",
    "source": "# # Do not forget to check if your notebook log collection plugin is working\n# from mining_extension import check_logging\n# check_logging(\"PASTE FULL URL HERE\")\nfrom mining_extension import check_logging \ncheck_logging(\"http://3.249.245.244:9999\")",
    "execution_count": 1
  },
  {
    "id": "d41df2fd19c6462aa7e6921aee0fe27f",
    "cell_type": "code",
    "source": "path = r'data\\task1\\jetnet_logs.txt'\n\nwith open(path, 'r') as f:\n    data = f.readlines()\n    # some lines contain several users let's split them\n    for i in range(len(data)):\n        l = data[i]\n        if l.count('@') > 1:\n            data[i] = l.split('@')\n            for j in range(len(data[i])):\n                data[i][j] = '@' + data[i][j]\n\n# to one list\ndata = [item for sublist in data for item in sublist if type(sublist) == list else sublist]",
    "execution_count": 2
  },
  {
    "id": "a10a66628bf74c818560ccc938191a47",
    "cell_type": "code",
    "source": "print(\"len data\", len(data))",
    "execution_count": 27
  },
  {
    "id": "92a3d7e63b244cf183603a0a383df177",
    "cell_type": "code",
    "source": "from datetime import datetime\nfrom re import match\n\ndef convert_line(line):\n    user = line.split(': ')[0]\n    actions = line.split(': ')[1]\n    actions = re.findall(r'(\\w+) \\w+(\\d+/\\d+/\\d+) \\| (\\d+:\\d+:\\d+)', actions)\n    actions = [(x[0], datetime.strptime(x[1] + ' | ' + x[2], '%d/%m/%y | %H:%M:%S')) for x in actions]\n    return (user, actions)\n\n# sessions = list(map(log_to_session, data))\nres = log_to_session(data[0])\nprint(res)",
    "execution_count": 20
  },
  {
    "id": "adab7d485ea644d58fe3d705733dde3a",
    "cell_type": "code",
    "source": "logs = list(map(log_to_session, data))",
    "execution_count": 14
  },
  {
    "id": "680d6ffff718494c89b764b833f3cbac",
    "cell_type": "code",
    "source": "print(\"len logs\", len(logs))",
    "execution_count": 15
  },
  {
    "id": "25d00bdd00c842afae0e1b87c3047aba",
    "cell_type": "code",
    "source": "print(\"Before\", data[-1])\nprint(\"After\", logs[-1])",
    "execution_count": 17
  },
