# The probability of repeating the same action three times in a row during one session
n_sessions = len(logs)

def in_row(log):
    actions = log[1]
    actions = list(map(lambda x: x[0], actions))
    for i in range(len(actions) - 2):
        if actions[i] == actions[i + 1] == actions[i + 2]:
            return True
    return False

n_in_row = 0
for log in logs:
    n_in_row += 1 if in_row(log) else 0

print("Probability of repeating the same action three times in a row during", n_in_row / n_sessions)

