    "source": "def split_lines(line):\n    ind = line[1:].find('@')\n    if ind == -1:\n        return [line]\n    else:\n        ind += 1\n        return [line[:ind]] + split_lines(line[ind:])\n\nlines2 = []\nfor line in lines:\n    for l in split_lines(line):\n        lines2.append(l)\n    \nlines = lines2\nlen(lines)",
