  {
    "id": "0bd369fb34fa4a858c735b22fdfabf1a",
    "cell_type": "code",
    "source": "import re\nfrom datetime import datetime\n\ndef parse(log):\n    name = log.split()[0][:-1]\n    log = log[len(name) + 2:]\n    log = re.split('-+>', log)\n    \n    actions = []\n    \n    for s in log:\n        s = s.strip()\n        if (len(s) > 0):\n            action_name = s.split()[0]\n            time = s[len(action_name):].strip()\n            if time[0] != '(':\n                time = '(' + time\n            if time == \"(null)\" or action_name == 'END':\n                continue\n            \n            time = datetime.strptime(time.strip(), '(%d/%m/%y | %H:%M:%S)')\n            actions.append((action_name, time))\n    return name, actions",
    "execution_count": 4
  },
  {
    "id": "517f2c75e6e74682a49494a2f2b40fe3",
    "cell_type": "code",
    "source": "parsed = list(map(parse, lines))\nparsed = list(filter(lambda x: len(x[1]) > 0, parsed))\nlen(parsed)",
    "execution_count": 5
  },
  {
    "id": "39798dafba614cffba2740f5a8c30d33",
    "cell_type": "code",
    "source": "parsed = sorted(parsed, key = lambda x: x[1][0][1])",
