    "source": "l = content.strip().split(\":\", 1)\n# print(l[1])\nl[1] = l[1].replace('-->', '->').strip().split('->')\n# print(l[1])\nl[1] = list(map(lambda x: x.strip().split(\" \", 1), l[1]))\n# actions = [t[0] for t in l[1]]\n# timestamps = [t[1] for t in l[1]]\nl",
    "execution_count": 12
  },
  {
    "id": "8f5f4f12092a481587a80f0a615c9011",
    "cell_type": "code",
    "source": "f = open('data/task1/jetnet_logs.txt')\nlines = f.readlines()\ncolumns = ['user_id', 'session_num', 'action_time','action_name']\ndf = pd.DataFrame([], columns = columns)\ndf",
    "execution_count": 20
  },
  {
    "id": "39c13efee459451e9af51e0fcef4f157",
    "cell_type": "code",
    "source": "d = []\nfor n, line in tqdm(enumerate(np.array(lines))):\n#     if n > 500: break\n    line = line.strip()\n    if line:\n        l = line.split(\":\", 1)\n        ids = l[0].replace('@', '')\n        l = l[1]\n        l = l.replace('-->', '\\t').replace('->', '\\t').strip().split('\\t')\n        for i, action in enumerate(np.array(l)):\n            action = action.strip().split(\" \", 1)\n            data = [ids, -1, '', '']\n            if len(action) == 2:\n                data[1]= i\n                data[2] = action[1].strip()[1:-1]\n                data[3] = action[0].strip()\n            d.append(data)",
    "execution_count": 28
  },
