  },
  {
    "id": "957e7579684046768a045858f7245066",
    "cell_type": "markdown",
    "source": "# Data Engineering"
  },
  {
    "id": "cfbf21dbe78541c38cc39a5c0dd1fd55",
    "cell_type": "code",
    "source": "data_path = \"data/task1/jetnet_logs.txt\"\n\nf = open(data_path, \"r\")\nlines = f.readlines()\nlen(lines)",
    "execution_count": 31
  },
  {
    "id": "4a86f94d49284b8c8f13125d3870ab24",
    "cell_type": "code",
    "source": "def split_lines(line):\n    ind = line[1:].find('@')\n    if ind == -1:\n        return [line]\n    else:\n        ind += 1\n        return [line[:ind]] + split_lines(line[ind:])\n\nlines2 = []\nfor line in lines:\n    for l in split_lines(line):\n        lines2.append(l)\n    \nlines = lines2\nlen(lines)",
    "execution_count": 32
  },
  {
    "id": "e7a693afe60f4e3a8dbc22582c749e0b",
    "cell_type": "code",
    "source": "import re\nfrom datetime import datetime\n\ndef parse(log):\n    name = log.split()[0][:-1]\n    log = log[len(name) + 2:]\n    log = re.split('-+>', log)\n    \n    actions = []\n    \n    for s in log:\n        s = s.strip()\n        if (len(s) > 0):\n            action_name = s.split()[0]\n            time = s[len(action_name):].strip()\n            if time[0] != '(':\n                time = '(' + time\n            if time == \"(null)\" or action_name == 'END':\n                continue\n            \n            time = datetime.strptime(time.strip(), '(%d/%m/%y | %H:%M:%S)')\n            actions.append((action_name, time))\n    return name, actions",
    "execution_count": 33
  },
  {
    "id": "7ea1c22d4c034b04862f7133fb7bbe25",
    "cell_type": "code",
    "source": "parsed = list(map(parse, lines))\nparsed = list(filter(lambda x: len(x[1]) > 0, parsed))\nlen(parsed)",
    "execution_count": 34
  },
  {
    "id": "3f4c629026d04143b2f79d0a1166f046",
    "cell_type": "code",
    "source": "parsed = sorted(parsed, key = lambda x: x[1][0][1])",
    "execution_count": 35
  },
  {
    "id": "36e3bdc862a845f682112ab6d8c53d2d",
    "cell_type": "code",
    "source": "parsed[-1]",
    "execution_count": 36
  },
  {
    "id": "1e36e6332811482ea60f3148e96d438e",
    "cell_type": "code",
    "source": "!pip install pandas",
    "execution_count": 37
  },
  {
    "id": "05e3c1028af9413b8a5bd50b5a57f611",
    "cell_type": "code",
    "source": "import pandas as pd\n\nsession_num = dict()\n\nuser_id_col = []\nsession_num_col = []\naction_time_col = []\naction_name_col = []\n\nfor (name, actions) in parsed:\n    curr_session = 0\n    if name in session_num:\n        curr_session = session_num[name] + 1\n    session_num[name] = curr_session\n    \n    for (action_name, time) in actions:\n        user_id_col.append(name)\n        session_num_col.append(curr_session)\n        action_time_col.append(time)\n        action_name_col.append(action_name)\n\ndf = pd.DataFrame({'user_id' : user_id_col, \n                   'session_num' : session_num_col, \n                   'action_time' : action_time_col, \n                   'action_name': action_name_col})\n\ndf",
    "execution_count": 38
