  {
    "cell_type": "code",
    "source": "# # Do not forget to check if your notebook log collection plugin is working\nfrom mining_extension import check_logging\ncheck_logging(\"http://3.249.245.244:9999\")",
    "execution_count": 1,
    "id": "f4af3e9a7dcd499c8c834bffa991cd49"
  },
  {
    "cell_type": "code",
    "source": "import numpy as np",
    "execution_count": 2,
    "id": "ad2eceff9e5743869f26cd0d6c4fef5c"
  },
  {
    "cell_type": "code",
    "source": "import pandas as pd\nfeatures_path = 'data/task2/'\ntest_features = pd.read_pickle(features_path+'test_features.pkl')\ntrain_features = pd.read_pickle(features_path+'train_features.pkl')\nvalidation_features = pd.read_pickle(features_path+'validation_features.pkl')\n\ntrain_features.index = range(train_features.shape[0])\nvalidation_features.index = range(validation_features.shape[0])\ntest_features.index = range(test_features.shape[0])\n\ntrain_features.fillna(0,inplace=True)\ntest_features.fillna(0,inplace=True)\nvalidation_features.fillna(0,inplace=True)\n\nprint(train_features.shape)\nprint(validation_features.shape)\nprint(test_features.shape)",
    "execution_count": 3,
    "id": "5b972747a15c469f9391607c74f4f4f1"
  },
  {
    "cell_type": "code",
    "source": "train_features",
    "execution_count": 4,
    "id": "3bfa5f40010b47b6bcf53dc8ae9c7ba4"
  },
  {
    "cell_type": "code",
    "source": "test_features.columns ",
    "execution_count": 5,
    "id": "02c7ecdf50ce4d7187dd081f87602e08"
  },
  {
    "cell_type": "code",
    "source": "numerics = ['int16', 'int32', 'int64', 'float16', 'float32', 'float64']\n\nnumerical_cols = test_features.select_dtypes(include=numerics).columns\nnumerical_cols",
    "execution_count": 6,
    "id": "9aea9178562846d79361ed5e48f68512"
  },
  {
    "cell_type": "code",
    "source": "train_num_features = train_features[numerical_cols]\nval_num_features = validation_features[numerical_cols] \ntest_num_features = test_features[numerical_cols]",
    "execution_count": 7,
    "id": "f82f9729ac8d4213bec963ec0ae260a4"
  },
  {
    "cell_type": "code",
    "source": "def get_mark_down(df):\n    mark_down = df['markdown_heading'].to_numpy()\n    arr = []\n\n    for a in mark_down:\n        if a == 0:\n            arr.append('')\n        else:\n            arr.append(a[0])\n\n    return arr       ",
    "execution_count": 8,
    "id": "2bebf80e591245bfb9dd1994484b13bc"
  },
  {
    "cell_type": "code",
    "source": "mark_down_train = get_mark_down(train_features)\nmark_down_val = get_mark_down(validation_features)\nmark_down_test = get_mark_down(test_features)",
    "execution_count": 9,
    "id": "8d26f59105fd4b109e3e3641b7db0527"
  },
  {
    "cell_type": "code",
    "source": "from sklearn.feature_extraction.text import TfidfVectorizer\n\nvectorizer = TfidfVectorizer()\nvectorizer.fit(mark_down_train)\nX_md_train = vectorizer.transform(mark_down_train)\nX_md_val = vectorizer.transform(mark_down_val)\nX_md_test = vectorizer.transform(mark_down_test)\nX_md_train.shape, X_md_val.shape, X_md_test.shape",
    "execution_count": 10,
    "id": "771051f9cbda4b9d8b36f8eb2d049fee"
  },
  {
    "cell_type": "code",
    "source": "from scipy.sparse import hstack",
    "execution_count": 11,
    "id": "290c443fea5e4456920c95862ad06ea6"
  },
  {
    "cell_type": "code",
    "source": "X_train = hstack((train_num_features.to_numpy(), X_md_train))\nX_val = hstack((val_num_features.to_numpy(), X_md_val))\nX_test = hstack((test_num_features.to_numpy(), X_md_test))",
    "execution_count": 12,
    "id": "4ec6bf161a9a440282c9bab640eba578"
  },
  {
    "cell_type": "code",
    "source": "!pip install scikit-learn",
    "execution_count": 13,
    "id": "44c1582bb1404f4d8a8c6b86d803ca1f"
  },
  {
    "cell_type": "code",
    "source": "from sklearn import preprocessing\n\nle = preprocessing.LabelEncoder()\nle.fit(train_features['primary_label'])\ny_train = le.transform(train_features['primary_label'])\ny_val = le.transform(validation_features['primary_label'])",
    "execution_count": 14,
    "id": "9dc8eb70f99f475a86c5542364547943"
  },
  {
    "cell_type": "code",
    "source": "from sklearn.ensemble import RandomForestClassifier\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.metrics import accuracy_score\nfrom sklearn.preprocessing import PolynomialFeatures\nfrom sklearn.metrics import f1_score\n\nbest_score = 0\nbest_depth = 0\n\nfor i in range(40, 71, 5):\n\n    clf = RandomForestClassifier(max_depth=i, n_estimators=100)\n\n    clf.fit(X_train, y_train)\n\n    pred = clf.predict(X_train)\n    print(i, \" train\", f1_score(pred, y_train, average='weighted'), end = '     ')\n\n    pred = clf.predict(X_val)\n    score = f1_score(pred, y_val, average='weighted')\n    print(\"val\", score)\n    \n    if score > best_score:\n        best_score = score\n        best_depth = i\n\nprint(\"Best score\", best_score, \"with max_depth\", best_depth)",
    "execution_count": 15,
    "id": "d9cf7d95844a43e7823b75790c65b19c"
  },
  {
    "cell_type": "code",
    "source": "clf = RandomForestClassifier(max_depth=best_depth, n_estimators=500)\n\nX_train_val = np.concatenate((X_train.toarray(), X_val.toarray()), axis=0)\ny_train_val = np.concatenate((y_train, y_val), axis=0)\n\nclf.fit(X_train_val, y_train_val)\n\npred = clf.predict(X_train_val)\nprint(i, \" train\", f1_score(pred, y_train_val, average='weighted'), end = '     ')\n\npred = clf.predict(X_test)",
    "execution_count": 21,
    "id": "16be460f1afc4d1d9a7c4275e4c04c29"
  },
  {
    "cell_type": "code",
    "source": "pred.shape",
    "execution_count": 22,
    "id": "873e514d5e364cd1b67d78725ed0a5ee"
  },
  {
    "cell_type": "code",
    "source": "vals = le.inverse_transform(pred)\nvals",
    "execution_count": 23,
    "id": "f323a42e14b047bc8de1c4f448972e7d"
  },
  {
    "cell_type": "code",
    "source": "df = pd.DataFrame({\"primary_label\" : vals })\ndf.head()",
    "execution_count": 26,
    "id": "d758cd5ee75a44db9002cae963b04f21"
  },
  {
    "cell_type": "code",
    "source": "df.to_csv('submission.csv', index=True)",
    "execution_count": 28,
    "id": "9577d73d565440178a67d7fda8ca71fd"
  }
]

