def create_session(session_id, day, user_id):
    return {  'SessionID': int(session_id), 
              'Day': int(day),
              'USERID': int(user_id) }

def create_query(session_id, time_passed, serp_id, query_id, list_of_terms, url_list):
    return {  'SessionID': int(session_id), 
              'TimePassed': int(time_passed),
              'SERPID': int(serp_id),
              'QueryID': int(query_id),
              'ListOfTerms': [int(t) for t in list_of_terms.split(',')],
              'URL_DOMAIN': [tuple(int(ui) for ui in u.split(','))
                                for u in url_list] }

def create_click(session_id,query_id,time_passed, serp_id, url_id):
    return {  'SessionID': int(session_id), 
              'QueryID': int(query_id),
              'TimePassed': int(time_passed),
              'SERPID': int(serp_id),
              'URLID': int(url_id) }

def create_mqc(file):
    m = []
    q = []
    c = []

    for line in open(file, "r"):
        sline = line.strip().split('\t')

        if len(sline) == 4:
            sid, _, day, uid = sline
            m.append(create_session(sid, day, uid))

        elif len(sline) == 16:
            sid, tp, _, serpid, quid, lot = sline[:6]
            lou = sline[6:]
            q.append(create_query(sid, tp, serpid, quid, lot, lou))

        elif len(sline) == 5:
            sid, tp, _, serpid, urlid = sline
            c.append(create_click(sid, quid, tp, serpid, urlid))
    return [m,q,c]

