def concat_text(df: pd.DataFrame) -> pd.DataFrame:
    df = df.copy()

    for col in ["text", "comment", "code_line_before", "code_line_after", "markdown_heading"]:
        df[col] = df.apply(lambda x: "\n".join(x) if isinstance(x, list) else x)
    return df

