from typing import List


def convert_packages_info(packages_info: List[List[str]], n: int = 20) -> pd.DataFrame:
    packages = [stat[0] for stat in c.most_common()]
    contains = {}
    # column for empty list of packages
    contains[-1] = [1 if len(info) == 0 else 0 for info in packages_info]
    # columns for most frequent packages
    for i, pcg in enumerate(stats[:n]):
        contains[i] = [1 if pcg in info else 0 for info in packages_info]
    # column for everything else
    contains[n] = [len(set(info) - set(packages[:n])) > 0 for info in packages_info] 
    return pd.DataFrame(contains)

convert_packages_info(train_features.packages_info.tolist()[:10])

