from tokenize import generate_tokens
class Readliner:
    def __init__(self, text_lines):
        self.text_lines = text_lines
        self.i = 0

    def __call__(self):
        if self.i < len(self):
            ctxt = self.text_lines[self.i]
            self.i += 1
            return ctxt
        return ''

    def __len__(self):
        return len(self.text_lines)

def tokenize_py(txt):
    try:
        return [i.string for i in generate_tokens(Readliner(txt))]
    except:
        return ['Fehler']

