def parse_action(action):
    action = action.strip()
    action_name, date = action.split(' ', 1)
    date = date.strip('(').strip(')')
    if date != 'null':
        try:
            date = datetime.strptime(date, "%d/%m/%y | %H:%M:%S")
        except Exception as e:
            print(date)
            print(action)
            raise e
    return action_name, date

all_rows = []
for i, row in enumerate(file_rows):
    try:
        user_name, actions = row.split(':', 1)
        actions = actions.replace('-->', '->')
        actions = actions.split('->')
        actions = [parse_action(action) for action in  actions if action.strip()]
        for action_name, action_time in actions:
            all_rows.append([i, user_name, action_name, action_time])
    except TypeError as e:
        print(actions)
        raise e
    except Exception as e:
        print(i, row)
        raise e
df = pd.DataFrame(all_rows).rename({0: 'session_num', 2: 'action_name', 1: 'user_id', 3: 'action_time'}, axis=1)

