def has_3_same(a):
    if len(a) < 3:
        return False
    for i in range(len(a) - 2):
        if a[i] == a[i + 1] == a[i + 2]:
            return True
    return False
df.groupby('session_num').\
    action_name.apply(list).
    apply(has_3_same).value_counts()

