    "source": "# Data Engineering"
  },
  {
    "id": "2448454d13c74b7f92d8ad37b79438d1",
    "cell_type": "code",
    "source": "import zipfile\n\n\nz = zipfile.ZipFile('data/task1/jetnet_logs.zip')\nz.namelist()",
    "execution_count": 2
  },
  {
    "id": "e809b06794cd4756871c782f24b6f4c3",
    "cell_type": "code",
    "source": "import io\nimport zipfile\n\nwith zipfile.ZipFile('data/task1/jetnet_logs.zip') as z:\n    with io.TextIOWrapper(z.open(\"jetnet_logs.txt\"), encoding=\"utf-8\") as f:\n        data_raw = f.read().split('\\n')",
    "execution_count": 3
  },
  {
    "id": "9ef1c427ce49495f840723a86144664a",
    "cell_type": "code",
    "source": "assert not [x for x in data_raw if x and not x.startswith('@User')]",
    "execution_count": 4
  },
  {
    "id": "f0f10ec5a8b14cc58b5ecb8af2d4aeb6",
    "cell_type": "code",
    "source": "from datetime import datetime\n\nuser_prefix = '@User'\nuser_id_start = len('@User')\naction_sep = '->'\naction_time_format = '(%d/%m/%y | %H:%M:%S)'\n\ndata = []\nfor row in data_raw:\n    if not row: continue\n    i = row.find(':')\n    uid = int(row[user_id_start:i])\n    \n    actions_raw = [x.strip() for x in row[i+1:].split(action_sep)]\n    if 'END' not in actions_raw[-1] or any('END' in x for x in actions_raw[:-1]): continue\n    \n    actions = []\n    is_legit_session = True\n    prev_a_time = None\n    for a in actions_raw:\n        i, j = a.find('('), a.find(')')\n        a_name = a[:i].strip()\n        if a_name == 'null':\n            is_legit_session = False\n            break\n        a_time_str = a[i:j+1]\n        try:\n            a_time = datetime.strptime(a_time_str, action_time_format)\n        except ValueError:\n            is_legit_session = False\n            break\n        if prev_a_time is not None and prev_a_time > a_time:\n            is_legit_session = False\n            break\n        actions.append((a_name, a_time))\n        prev_a_time = a_time\n    if is_legit_session:\n        data.append([uid, actions])\n    \nlen(data)\n        \n    ",
    "execution_count": 5
  },
  {
    "id": "171dc853b42147089aa92851af6dbf75",
    "cell_type": "code",
    "source": "data.sort(key=lambda x: x[-1][0][-1])\ndata[:3]",
    "execution_count": 6
  },
  {
    "id": "4badefa5f14c451284c53c1954b548a8",
