  {
    "id": "92cd57b9c63a43fd89f89c5b9005a6ae",
    "cell_type": "code",
    "source": "import pandas as pd\nimport numpy as np\n\ncol_names = ['user_id', 'session_num', 'action_time', 'action_name']\ndata_df = []\n\nfor sid, (uid, actions) in enumerate(data):\n    for a_name, a_time in actions:\n        data_df.append((uid, sid, a_time, a_name))\ndf = pd.DataFrame(data_df, columns=col_names)\ndf.head()\n    \n    ",
    "execution_count": 8
