    "id": "968e8007e99149608492f90df00d894e",
    "cell_type": "markdown",
    "source": "# Metrics Evaluation"
  },
  {
    "id": "b8b44226e3e14ffb949ead90914ca2b1",
    "cell_type": "markdown",
    "source": "### Mean actions count per user overall"
  },
  {
    "id": "73c9675ae7ad48d6949caa5c29f5cbff",
    "cell_type": "code",
    "source": "df.groupby('user_id').size().mean()",
    "execution_count": 10
